CREATE TABLE "DeliveryReceipt" (
  "id" TEXT NOT NULL,
  "userId" TEXT NOT NULL,
  "recipientEmail" TEXT NOT NULL,
  "createdAt" TIMESTAMP(3) NOT NULL,
  "sentAt" TIMESTAMP(3) NOT NULL,
  CONSTRAINT "DeliveryReceipt_pkey" PRIMARY KEY ("id"),
  CONSTRAINT "DeliveryReceipt_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE
);
CREATE INDEX "DeliveryReceipt_userId_sentAt_idx" ON "DeliveryReceipt"("userId", "sentAt");
CREATE INDEX "DeliveryReceipt_userId_recipientEmail_idx" ON "DeliveryReceipt"("userId", "recipientEmail");

-- Transfer only eligible soft-deleted history, atomically with its removal.
BEGIN;
LOCK TABLE "Send" IN SHARE ROW EXCLUSIVE MODE;
INSERT INTO "DeliveryReceipt" ("id", "userId", "recipientEmail", "createdAt", "sentAt")
SELECT gen_random_uuid()::text, c."userId", s."recipientEmail", s."createdAt", s."sentAt"
FROM "Send" s JOIN "Campaign" c ON c.id = s."campaignId"
WHERE s."historyDeletedAt" IS NOT NULL AND s.status IN ('SENT', 'REPLIED')
  AND s."deliveryState" NOT IN ('ATTEMPTING', 'UNCERTAIN') AND s."sentAt" IS NOT NULL;
DELETE FROM "Send" WHERE "historyDeletedAt" IS NOT NULL
  AND status IN ('SENT', 'REPLIED', 'FAILED', 'CANCELLED')
  AND "deliveryState" NOT IN ('ATTEMPTING', 'UNCERTAIN');
UPDATE "Campaign" c SET role = '', "attachmentId" = NULL
WHERE NOT EXISTS (SELECT 1 FROM "Send" s WHERE s."campaignId" = c.id);
COMMIT;
